"""The risk.Drawdown sample: one ticker's fall from its peak to its trough; a ticker with no fall."""

from risk import Drawdown


def test_sample_holds_the_drawdown_invariants(contract_sample):
    first_date = contract_sample("mdata.Prices")["dates"][0]
    fall, no_fall = (Drawdown(**row) for row in contract_sample("risk.Drawdown")["drawdowns"])

    assert fall.depth < 0
    assert fall.peak_date < fall.trough_date
    assert no_fall.depth == 0
    assert no_fall.peak_date == no_fall.trough_date == first_date
"""The risk.Returns sample: two tickers' log returns over five dates."""

from risk import Returns


def test_sample_holds_the_returns_invariants(contract_sample):
    prices = contract_sample("mdata.Prices")
    data = contract_sample("risk.Returns")
    returns = Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={ticker: tuple(values) for ticker, values in data["values"].items()},
    )

    assert returns.base_date == prices["dates"][0]
    assert list(returns.dates) == prices["dates"][1:]
    assert returns.tickers == ("AAA", "BBB")
    for ticker in returns.tickers:
        assert len(returns.values[ticker]) == len(returns.dates) == 5
